      const wb = getCharWorldbookNames('current'), names = getWorldbookNames();
      return wb && wb.primary && names.includes(wb.primary) ? 'ok' : 'missing';
    } catch (e) { return ''; }
  }
  function diagnose() {
    const st = lorebookStatus();
    const why = st === 'ok'
      ? 'No game state in this chat. The card\'s lorebook is attached, so check that <b>MagVarUpdate</b> and <b>Tavern Helper</b> are enabled, then start a new chat.'
      : 'No game state: the <b>card\'s lorebook is not attached</b> to this character' + (st ? '' : ' (or MagVarUpdate is not running)') + '. Import it (SillyTavern asks before overwriting), then start a <b>new chat</b>: the opening message takes its starting state from the lorebook.';
    band.className = 'band';
    band.innerHTML = '<div class="cta"><span>' + why + '</span>' + (st === 'ok' ? '' : '<button class="btn primary" data-importlore="1">Import the card\'s lorebook</button>') + '</div>';
  }
  function importLore() {   // SillyTavern: character panel → More… → Import Card Lore
    try {
      const pd = window.parent.document, sel = pd.getElementById('char-management-dropdown'), opt = pd.getElementById('import_character_info');
      if (!sel || !opt) throw new Error('menu not found');
      sel.selectedIndex = Array.from(sel.options).indexOf(opt);
      sel.dispatchEvent(new Event('change', { bubbles: true }));
    } catch (e) {
      band.querySelector('.cta span').innerHTML += '<br>Open the character panel → <b>More…</b> → <b>Import Card Lore</b>.';
    }
  }

  let who = id => id;
  function render() {
    if (!isLatest()) { band.className = 'band stale'; band.innerHTML = ''; return; }
    const S = readState();
    // v1.0.3 (A#5, D14): an NPC is named once Rank >= 1 or the story named them; before that, their descriptor
    who = id => (CAST[id] ? ((((S || {}).Bonds || {})[id] || {}).Rank >= 1 || (((S || {}).$ui || {}).names || []).includes(id) ? CAST[id][2] : CAST[id][1]) : id);
    if (!S) { band.className = 'band'; band.innerHTML = '<div class="waiting">Syncing the bracelet…</div>'; return; }
    const W = S.World || {}, P = (S.Player || {}).Profile || {}, V = (S.Player || {}).Vitals || {};
    const ui = S.$ui || {}, unl = ui.unlocks || [], M = S.Magic || {}, T = M._Techniques || {}, H = S.Hidden || {};
    band.style.setProperty('--dorm', DORM[P.Dorm] || DORM.Unsorted);
    const upkeep = Object.values(M.Active || {}).reduce((a, e) => a + num((T[e.Technique] || {}).Upkeep_per_min, 0), 0);

    let h = '<div class="top"><div class="glass">'
      + '<div class="clock"><span class="t">' + esc(W.Day) + ' ' + esc(W.Time) + '</span><span class="d">Month ' + esc(W.Month) + ', Week ' + esc(W.Week) + '</span></div>'
      + '<div class="period">' + esc(W._Period || 'Free time') + '</div>'
      + '<div class="loc"><i class="fa-solid fa-location-dot"></i> ' + esc(W.Location) + '</div>'
      + '</div><div class="side"><div class="pts">' + fmt((S.Player.Wallet || {}).Points) + '<small>pts</small></div>'
      + '<div class="dorm">' + esc(P.Dorm === 'Unsorted' || !P.Dorm ? 'Unsorted' : P.Dorm + (P.Dorm_rank ? ' #' + P.Dorm_rank : '')) + '</div></div></div>';

    h += '<div class="vitals">'
      + bar('Health', num(V.HP, 0), num(V.HP_max, 100), 'var(--hp)', V._Condition || '', sevCls(V._Condition || ''))
      + bar('Stamina', num(V.Stamina, 0), num(V.Stamina_max, 100), 'var(--st)', V._Fatigue || '', fatCls(V._Fatigue || ''))
      + bar('Mana', num(V.Mana, 0), num(V.Mana_max, 100), 'var(--mp)', upkeep > 0 ? 'Upkeep −' + fmt(upkeep) + '/min' : (Object.keys(T).length ? Object.keys(T).length + ' techniques' : 'No techniques yet'), upkeep > 0 ? 'mid' : '')
      + '</div>';

    const c = [];
    // 1.1.0: features that are off hide their chips (Student file > Settings > Features)
    const OFF = ui.off || [], on = id => !OFF.includes(id);
    const wx = ui.wx, wxm = ui.wxfx || 'full';
    if (wxm !== 'off' && wx && wx.now && !wx.away && W._Weather) {
      const n = wx.now, ic = n.rare === 'lightning storm' ? 'fa-bolt' : n.sky === 'Storm' ? 'fa-cloud-bolt' : n.snow ? 'fa-snowflake' : n.sky === 'Rain' ? (n.rain === 'heavy' ? 'fa-cloud-showers-heavy' : 'fa-cloud-rain')
        : n.sky === 'Fog' ? 'fa-smog' : n.sky === 'Overcast' ? 'fa-cloud' : n.sky === 'Cloudy' ? 'fa-cloud-sun' : n.wind ? 'fa-wind' : wx.block === 2 ? 'fa-moon' : 'fa-sun';
      c.push(chip(n.temp + ' °C' + (n.wind ? ', ' + n.wind : '') + (n.rare ? ', ' + n.rare : ''), ic, n.rare ? 'warn' : '', W._Weather));
    }
    if (wxm === 'full' && unl.includes('conditions')) {
      const CI = { Soaked: 'fa-droplet', Chilled: 'fa-temperature-low', Overheated: 'fa-temperature-high', 'Head cold': 'fa-head-side-cough' };
      Object.entries((S.Player || {}).Conditions || {}).forEach(([k, v]) => c.push(chip(k, CI[k] || 'fa-circle-exclamation', 'warn', (v && v.Effect) || k, 'profile')));
    }
    if (W._Event_today) c.push(chip(W._Event_today.split(/ \| |;/)[0].split(' — ')[0].split(' (')[0], 'fa-star', 'glow', W._Event_today));
    // 1.3.4 (owner): what comes next today (engine $ui.next): an event's timed item, a class, curfew
    const nx = ui.next;
    if (nx && nx.at) c.push(chip('Next ' + nx.at + ' · ' + nx.what, nx.kind === 'curfew' ? 'fa-moon' : nx.kind === 'class' ? 'fa-book-open' : 'fa-clock', nx.kind === 'event' ? 'glow' : '', 'Next today: ' + nx.at + ', ' + nx.what, 'notebook:planner'));
    if (W._Curfew) c.push(chip(/LOCKDOWN/.test(W._Curfew) ? 'Lockdown' : /Break/.test(W._Curfew) ? 'Break' : /^Away/.test(W._Curfew) ? 'Away' : 'Curfew', /^Away/.test(W._Curfew) ? 'fa-route' : 'fa-moon', /LOCKDOWN|CURFEW/.test(W._Curfew) ? 'danger' : 'warn', W._Curfew));
    const inj = Object.keys((S.Player || {}).Injuries || {});
    if (unl.includes('injuries') && inj.length) c.push(chip(inj.length === 1 ? inj[0] : inj.length + ' injuries', 'fa-bandage', 'danger', inj.join(', ')));
    const act = Object.keys(M.Active || {});
    if (act.length) c.push(chip(act.join(', '), 'fa-wand-sparkles', 'glow', 'Active effects'));
    const summoned = Object.entries(M.Pacts || {}).filter(([, p]) => p.Summoned).map(([k]) => k);
    if (unl.includes('pacts') && summoned.length) c.push(chip(summoned.join(', ') + ' summoned', 'fa-feather', 'glow'));
    if (unl.includes('hidden') && H._True_magic) c.push(chip('Doves: ' + (H._Stage || 'Unnoticed'), 'fa-eye', num(H.Dove_attention, 0) >= 40 ? 'danger' : num(H.Dove_attention, 0) >= 20 ? 'warn' : '', 'Dove attention ' + num(H.Dove_attention, 0) + '/100'));
    if ((S.Battle || {}).Active && on('battle')) c.push(chip('In battle: ' + Object.keys(S.Battle.Combatants || {}).map(k => CAST[k] && !(((S.Bonds || {})[k] || {}).Rank >= 1 || (ui.names || []).includes(k)) ? CAST[k][1] : k).join(', '), 'fa-khanda', 'danger', 'Open the battle panel', 'battle'));
    // 1.2.2: a full bond bar opens a bond event; the chip says where it is likely to happen
    const bev = ui.bev || {}, ready = Object.entries(S.Bonds || {}).filter(([, b]) => b && b._Event_ready).map(([k]) => [who(k), (bev[k] || {}).where || '', (bev[k] || {}).when || '']);
    if (ready.length) c.push(chip('Bond event: ' + ready.map(r => r[0] + (r[1] ? ' (' + r[1] + ')' : '')).join(', '), 'fa-heart', 'warn', ready.map(r => r[0] + ': ' + (r[1] || 'where they usually are') + (r[2] ? ', ' + r[2] : '')).join('\n'), 'people'));
    const com = on('planner') ? Object.entries(S.Commitments || {}) : [], late = com.filter(([, x]) => x && x._Late).map(([k]) => k);
    const soon = com.filter(([, x]) => x && !x._Late && /^today/.test(x._When || '')).map(([k]) => k);
    if (late.length) c.push(chip('Overdue: ' + late.join(', '), 'fa-triangle-exclamation', 'danger', 'Open the planner', 'notebook:planner'));
    else if (soon.length) c.push(chip('Due today: ' + soon.join(', '), 'fa-thumbtack', 'warn', 'Open the planner', 'notebook:planner'));
    else if (unl.includes('planner') && com.length) c.push(chip(com.length + (com.length === 1 ? ' commitment' : ' commitments'), 'fa-thumbtack', '', com.map(([k]) => k).join(', '), 'notebook:planner'));
    const mail = Object.values(S.Letters || {}).filter(l => l && l.Status === 'waiting').length;
    if (unl.includes('letters') && mail && on('letters')) c.push(chip(mail === 1 ? 'Letter waiting' : mail + ' letters waiting', 'fa-envelope', 'glow', 'At the Mail Tower', 'notebook:letters'));
    const hap = ui.hap;   // 5.3 (F20): today's campus happening
    if (hap && hap.text && ui.happenings !== 'off') c.push(chip((hap.now ? 'Now: ' : hap.from + ':00 ') + (hap.where || 'Around campus'), 'fa-bullhorn', hap.now ? 'glow' : '', hap.text, 'notebook:planner'));
    // 1.2.0: at a shop (Commissary, the Mall and its shops) a chip opens the Shop tab, which exists only there
    if (/^(the\s+)?(commissary|mall|nightwell|merryhew'?s|snug)\b/i.test(String(W.Location || '').trim())) c.push(chip('Shop here', 'fa-basket-shopping', '', 'Open the shop list', 'activities:shop'));
    if (c.length) h += '<div class="chips">' + c.join('') + '</div>';

    const here = Object.entries((S.Scene || {}).Present || {});
    if (here.length) {
      h += '<div class="cast" aria-label="Here with you">' + here.map(([id, v]) => {
        const c = CAST[id], b = (S.Bonds || {})[id];
        const known = c && ((b && b.Rank >= 1) || (ui.names || []).includes(id));
        const label = c ? (known ? c[2] : c[1]) : id;
        const tip = label + (v && v.Note ? ': ' + v.Note : '');
        const face = c ? '<img class="face" style="border-color:' + c[3] + '" src="' + esc(BASE + c[0]) + '" alt="" data-fb="' + (known ? esc(c[2].slice(0, 2)) : '?') + '">'
          : '<span class="face" style="border-color:#6f737b">' + esc(id.split(/\s+/).map(w => w[0]).join('').slice(0, 2)) + '</span>';
        // 1.6.1 (N5): an invented character's button pins them in the Extras record (Keep) or lets them go
        const xr = !c ? ((S.Extras || {})[id] || null) : null, pin = xr && xr.Keep;
        const xtip = !c ? (pin ? ' (kept: tap to let them go)' : ' (tap to keep them in the record of invented characters)') : '';
        return '<button ' + (c ? 'data-open="npc:' + esc(id) + '"' : 'data-keep="' + esc(id) + '"') + ' title="' + esc(tip + xtip) + '">' + face + '<span class="nm">' + (pin ? '<i class="fa-solid fa-thumbtack"></i> ' : '') + esc(known || !c ? (c ? c[2] : id) : '?') + '</span></button>';
      }).join('') + '</div>';
    }

    const news = (ui.toasts || []).slice(-4).map(t => String(t).replace(/\{npc:([^}]+)\}/g, (_m, id) => who(id)));
    if (news.length) h += '<div class="news">' + news.map(t => '<div>' + esc(t) + '</div>').join('') + '</div>';

    if (!ui.built) h += '<div class="cta"><span>Your student file is empty. Set up your student before your first action.</span><button class="btn primary" data-open="builder">Create your student</button></div>';

    h += '<div class="actions"><button class="btn" data-open="profile"><i class="fa-solid fa-id-card"></i> Student file</button>'
      + '<button class="btn" data-open="people"><i class="fa-solid fa-users"></i> People</button>'
      + '<button class="btn" data-open="map"><i class="fa-solid fa-map"></i> Map</button>'
      + '<button class="btn" data-open="notebook"><i class="fa-solid fa-book"></i> Notebook</button>'
      + '<button class="btn" data-open="activities"><i class="fa-solid fa-compass"></i> Activities</button>'
      + '<button class="btn opt" data-open="builder"><i class="fa-solid fa-pen-nib"></i> Builder</button>'
      + '<button class="btn ghost" data-toggle="1" aria-label="Collapse or expand" aria-expanded="' + (!collapsed) + '" title="' + (collapsed ? 'Expand' : 'Collapse') + '"><i class="fa-solid ' + (collapsed ? 'fa-chevron-down' : 'fa-chevron-up') + '"></i></button></div>';

    band.className = 'band' + (collapsed ? ' collapsed' : '');
    band.innerHTML = h;
    band.querySelectorAll('img[data-fb]').forEach(img => img.addEventListener('error', () => {
      const sp = document.createElement('span'); sp.className = 'face'; sp.style.borderColor = img.style.borderColor; sp.textContent = img.dataset.fb; img.replaceWith(sp);
    }, { once: true }));
    popToasts(news);
  }

  function popToasts(news) {
    if (!news.length || typeof toastr === 'undefined') return;
    let chat = ''; try { chat = SillyTavern.getCurrentChatId(); } catch (e) {}
    const key = 'eld.toast.' + chat + '.' + MID + '.' + news.join('|').length + news.join('|').slice(0, 60);
    try { if (sessionStorage.getItem(key)) return; sessionStorage.setItem(key, '1'); } catch (e) { return; }
    news.forEach(t => toastr.info(t, 'Bracelet', { timeOut: 4500 }));
  }

  band.addEventListener('click', ev => {
    const b = ev.target.closest('button'); if (!b) return;
    if (b.dataset.importlore) { importLore(); return; }
    if (b.dataset.toggle) { collapsed = !collapsed; try { localStorage.setItem('eld.bar.collapsed', collapsed ? '1' : '0'); } catch (e) {} render(); return; }
    if (b.dataset.keep) {
      if (!window.parent.__eldrasilUI) { if (typeof toastr !== 'undefined') toastr.warning('Turn on the "Eldrasil UI" script in Tavern Helper → Scripts.', 'Eldrasil'); return; }
      eventEmit('eldrasil:keep', b.dataset.keep); return;
    }
    if (b.dataset.open) {
      if (!window.parent.__eldrasilUI) { if (typeof toastr !== 'undefined') toastr.warning('Turn on the "Eldrasil UI" script in Tavern Helper → Scripts.', 'Eldrasil'); return; }
      eventEmit('eldrasil:open', b.dataset.open);
    }
  });

  const rerender = _.debounce(render, 250);
  try {
    ['MESSAGE_RECEIVED', 'MESSAGE_SENT', 'MESSAGE_DELETED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED', 'MESSAGE_EDITED', 'CHAT_CHANGED'].forEach(k => {
      if (tavern_events[k]) eventOn(tavern_events[k], rerender);
    });
    eventOn('eldrasil:state', rerender);
    waitGlobalInitialized('Mvu').then(() => {
      eventOn(Mvu.events.VARIABLE_INITIALIZED, rerender);
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => setTimeout(rerender, 400));
    });
  } catch (e) { console.warn('[Eldrasil bar]', e); }
  render();
  // keep looking for the state for a minute; after 4 s without one, explain why (it may still arrive: then the bracelet shows)
  let tries = 0; const poll = setInterval(() => { if (readState()) { clearInterval(poll); render(); return; } if (++tries === 4) diagnose(); if (tries > 60) clearInterval(poll); }, 1000);
})();
</script>
